def maxValue(nums, k):
    n = len(nums)

    def prefix_sets(arr):
        # res[i] = set of OR values obtainable using exactly k of arr[0:i]
        res = [set() for _ in range(len(arr) + 1)]
        dp = [set() for _ in range(k + 1)]
        dp[0].add(0)
        for i, x in enumerate(arr):
            for c in range(min(k, i + 1), 0, -1):
                for v in dp[c - 1]:
                    dp[c].add(v | x)
            res[i + 1] = set(dp[k])
        return res

    A = prefix_sets(nums)            # A[i]: OR of k picked from first i
    B = prefix_sets(nums[::-1])      # B[t]: OR of k picked from last t
    ans = -1
    for i in range(k, n - k + 1):
        sa = A[i]
        sb = B[n - i]
        if not sa or not sb:
            continue
        for a in sa:
            for b in sb:
                if (a ^ b) > ans:
                    ans = a ^ b
    return ans
